def gid(*parts):
    return 'G' + hashlib.sha256('|'.join(parts).encode()).hexdigest()[:10]

def main():
    gold = {r['faq_id']: r for r in csv.DictReader(open('02_Data/04_Gold/hotel_faq_gold.csv', encoding='utf-8-sig'))}
    out = []
    for iid, anchor, egy, src, mode, tool, qs in E:
        if anchor.startswith('FAQ'):
            a = gold[anchor]
            assert a['language'] == 'Arabic', anchor
            msa = a['answer']
        else:
            msa = anchor
        plain = 0
        for q in qs:
            if q.startswith('!'):
                qt, q = 'Scenario', q[1:]
            else:
                qt = 'Direct' if plain == 0 else 'Paraphrased'; plain += 1
            out.append({'intent_id': iid, 'intent_name': NAMES[iid][0], 'language': 'Arabic-Egyptian',
                        'question_type': qt, 'question': q, 'answer': msa, 'status': 'valid',
                        'category': NAMES[iid][1], 'source': src, 'origin': 'egyptian_dialect_v3',
                        'response_mode': mode or MODE.get(iid, 'knowledge_answer'),
                        'requires_tool': tool, 'answer_egyptian': egy,
                        'group_id': gid('egy3', iid, egy)})
    for iid, src, ans, qs in CORE:
        for lang in ('English', 'Arabic', 'French', 'Russian'):
            for k, q in enumerate(qs[lang]):
                out.append({'intent_id': iid, 'intent_name': NAMES[iid][0], 'language': lang,
                            'question_type': 'Direct' if k == 0 else 'Paraphrased', 'question': q,
                            'answer': ans[lang], 'status': 'valid', 'category': NAMES[iid][1],
                            'source': src, 'origin': 'coverage_fill_v3',
                            'response_mode': 'knowledge_answer', 'requires_tool': 'False',
                            'answer_egyptian': '', 'group_id': gid('core3', iid, lang, ans['English'])})
    os.makedirs(os.path.dirname(OUT), exist_ok=True)
    with open(OUT, 'w', newline='', encoding='utf-8') as f:
        w = csv.DictWriter(f, fieldnames=list(out[0].keys())); w.writeheader(); w.writerows(out)
    from collections import Counter
    print(f'{OUT}: {len(out)} rows  {dict(Counter(r["origin"] for r in out))}')

if __name__ == '__main__':
    main()
